#!/usr/bin/env node
// Bundles every ModuleScript under src/ into one Luau file for
//   loadstring(game:HttpGet(url))()
//
// Source uses Luau string requires:
//   local Signal = require("@self/Core/Signal")
//   local New = require("@self/../Core/New")
// which luau-lsp resolves (with real type inference) and this script rewrites
// into lookups against the generated module table.
import fs from "node:fs";
import path from "node:path";
import { buildTree } from "./tree.mjs";

const srcDir = process.argv[2] ?? "src";
const rootName = process.argv[3] ?? "Loom";
const outFile = process.argv[4] ?? "dist/loom.lua";

const { modules } = buildTree(srcDir, rootName);

const fileToModule = new Map();
for (const [id, mod] of modules) {
  fileToModule.set(path.resolve(mod.filePath), id);
}

function resolveRequire(spec, fromFile) {
  const fromDir = path.dirname(fromFile);
  const raw = spec.startsWith("@self/") ? spec.slice("@self/".length) : spec;
  const base = spec.startsWith("@self") || spec.startsWith(".") ? path.resolve(fromDir, raw) : path.resolve(raw);

  const candidates = [
    `${base}.luau`,
    `${base}.lua`,
    path.join(base, "init.luau"),
    path.join(base, "init.lua"),
    base,
  ];
  const found = candidates.map((c) => fileToModule.get(c)).find(Boolean);
  if (!found) {
    throw new Error(`cannot resolve require("${spec}") from ${path.relative(process.cwd(), fromFile)}`);
  }
  return found;
}

const REQUIRE_RE = /\brequire\(\s*("(?:[^"\\]|\\.)*"|'(?:[^'\\]|\\.)*')\s*\)/g;

const bodies = [];

for (const [id, mod] of [...modules.entries()].sort(([a], [b]) => a.localeCompare(b))) {
  let source = fs.readFileSync(mod.filePath, "utf8");
  if (source.charCodeAt(0) === 0xfeff) source = source.slice(1);

  source = source.replace(REQUIRE_RE, (_match, literal) => {
    const spec = literal.slice(1, -1);
    return `__require(${JSON.stringify(resolveRequire(spec, mod.filePath))})`;
  });

  const stray = source
    .split("\n")
    .findIndex((line) => !line.trim().startsWith("--") && /(^|[^.\w"'])script(\W|$)/.test(line));
  if (stray >= 0) {
    console.error(`error: bare 'script' reference in ${id} at line ${stray + 1}`);
    process.exit(1);
  }

  bodies.push(`__mods[${JSON.stringify(id)}] = function()\n${source.replace(/\s*$/, "")}\nend\n`);
}

const header = `--[[
\tLoom - bundled build. Generated by \`npm run build\`; edit src/, not this.

\tlocal Loom = loadstring(game:HttpGet("https://raw.githubusercontent.com/.../loom.lua"))()
\tlocal Window = Loom:CreateWindow({ Name = "My Script" })
]]

local __mods = {}
local __cache = {}

local function __require(id: string)
\tlocal cached = __cache[id]
\tif cached == false then
\t\treturn nil
\telseif cached ~= nil then
\t\treturn cached
\tend

\tlocal module = __mods[id]
\tif module == nil then
\t\terror(\`[Loom] unknown module {id}\`, 2)
\tend

\t-- false marks "loaded, returned nil" so cyclic requires terminate.
\t__cache[id] = false
\tlocal ok, result = pcall(module)
\tif not ok then
\t\terror(\`[Loom] {id} failed to load: {result}\`, 2)
\tend

\t__cache[id] = result or false
\treturn result
end

`;

const footer = `\nreturn __require(${JSON.stringify(rootName)})\n`;

fs.mkdirSync(path.dirname(outFile), { recursive: true });
fs.writeFileSync(outFile, header + bodies.join("\n") + footer);

const bytes = fs.statSync(outFile).size;
console.log(`bundled ${bodies.length} modules -> ${outFile} (${(bytes / 1024).toFixed(1)} KB)`);
